# Datasources: https://sparql.uniprot.org/sparql/ https://sparql.rhea-db.org/sparql https://www.bgee.org/sparql
PREFIX CHEBI: <http://purl.obolibrary.org/obo/CHEBI_>
PREFIX genex: <http://purl.org/genex#>
PREFIX lscr: <http://purl.org/lscr#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rh: <http://rdf.rhea-db.org/>
PREFIX taxon: <http://purl.uniprot.org/taxonomy/>
PREFIX up: <http://purl.uniprot.org/core/>
SELECT DISTINCT ?protein ?ensemblGene ?reaction ?anatomicEntityLabel ?anatomicEntity
WHERE {
  # federated query to Rhea enadpoint
  {
    SELECT DISTINCT ?reaction WHERE {
	{
        ?reaction rdfs:subClassOf rh:Reaction ;
          rh:equation ?reactionEquation ;
          rh:side ?reactionSide .
        ?reactionSide rh:contains ?participant .
        ?participant rh:compound ?compound .
        # compound constraint (CHEBI:16113 == cholesterol)
        ?compound rh:chebi CHEBI:16113 .
      }
    }
  }
  # taxonomy constraint (taxon:9606 == Homo sapiens)
  ?protein up:organism taxon:9606 ;
    up:annotation ?a ;
    rdfs:seeAlso / up:transcribedFrom ?ensemblGene .
  ?a a up:Catalytic_Activity_Annotation ;
    up:catalyticActivity ?ca .
  ?ca up:catalyzedReaction ?reaction .
  # federated query to Bgee (expression data)
  BIND(IRI(REPLACE(STR(?ensemblGene), "\\.[0-9]+$", "")) AS ?ensemblGeneNoVersion)
	{
    ?gene lscr:xrefEnsemblGene ?ensemblGeneNoVersion ;
      genex:isExpressedIn ?anatomicEntity .
    ?anatomicEntity rdfs:label ?anatomicEntityLabel .
  }
}

# Datasources: https://biosoda.unil.ch/emi/sparql https://qlever.cs.uni-freiburg.de/api/wikidata
PREFIX emi: <https://purl.org/emi#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?wdx_Source ?sourceNameURI ?intxnLabel ?intxnType ?wdx_Target ?targetNameURI
WHERE {
	{
		SELECT DISTINCT ?wdx_Target ?targetName ?sourceName ?wdx_Source ?intxnType
		WHERE {
			# first select the source-target interaction-pairs
			?intxn emi:hasSource ?source ;
			emi:hasTarget ?target ;
				emi:isClassifiedWith ?intxnType .    # unidirectional interaction, e.g.: source-X hosts target target-Y
			?intxnType rdfs:label ?intxnLabel .
			?source emi:inTaxon ?wdx_Source ;          # retrieve wikidata-id for source
				sosa:isSampleOf ?sourceName .       # scientific name of source as given in GloBI
			?target emi:inTaxon ?wdx_Target ;          # retrieve wikidata-id for target
				sosa:isSampleOf ?targetName .        # scientific name of target as given in GloBI
		}
	}
		{
		{
			?wdx_Source wdt:P141 wd:Q719675 ;        # filter source wikidata ids, which have IUCN status (wdt:P141) as near threatened (wd:Q719675) and which is a plant
				wdt:P171* wd:Q879246 .
		} UNION {
			?wdx_Target wdt:P141 wd:Q719675 ;        # filter target wikidata ids, which have IUCN status (wdt:P141) as near threatened (wd:Q719675) and which is a plant
				wdt:P171* wd:Q879246 .
		}
	}
	BIND(REPLACE(STR(?sourceName), "%20", " ") AS ?sourceNameX)    # remove percent-encoding for scientific names of source-X
	BIND(IRI(?sourceNameX) AS ?sourceNameURI)
	BIND(REPLACE(STR(?targetName), "%20", " ") AS ?targetNameX)    # remove percent-encoding for scientific names of target-Y
	BIND(IRI(?targetNameX) AS ?targetNameURI)
}

